const themeButton = document.querySelector('.theme');
const languageButton = document.querySelector('.language');
let language = 'en';
try { language = localStorage.getItem('portfolio-language') || (navigator.language.toLowerCase().startsWith('pt') ? 'pt' : 'en'); } catch {}
try { if (localStorage.getItem('portfolio-theme') === 'light') document.body.classList.add('light'); } catch {}

function updateThemeLabel() {
  const key = document.body.classList.contains('light') ? 'themeDark' : 'themeLight';
  themeButton.setAttribute('aria-label', translations[language][key]);
  themeButton.title = translations[language][key];
}

function applyLanguage(nextLanguage) {
  language = nextLanguage;
  const copy = translations[language];
  document.documentElement.lang = language === 'pt' ? 'pt-BR' : 'en';
  document.querySelectorAll('[data-i18n]').forEach((element) => { element.textContent = copy[element.dataset.i18n]; });
  document.querySelectorAll('[data-i18n-html]').forEach((element) => { element.innerHTML = copy[element.dataset.i18nHtml]; });
  document.querySelectorAll('[data-i18n-alt]').forEach((element) => { element.alt = copy[element.dataset.i18nAlt]; });
  languageButton.textContent = language === 'pt' ? 'EN' : 'PT';
  languageButton.setAttribute('aria-label', copy.languageLabel);
  document.querySelector('#copy').setAttribute('aria-label', copy.copyLabel);
  document.querySelector('#copy').title = copy.copyLabel;
  document.title = language === 'pt' ? 'Cristian Macedo — Engenheiro de Software' : 'Cristian Macedo — Software Engineer';
  document.querySelector('meta[name="description"]').content = language === 'pt' ? 'Cristian Macedo — engenheiro de software frontend sênior atuando entre produto, arquitetura e experiência de desenvolvimento.' : 'Cristian Macedo — senior frontend software engineer working across product, architecture, and developer experience.';
  document.querySelector('#copy-status').textContent = '';
  updateThemeLabel();
  try { localStorage.setItem('portfolio-language', language); } catch {}
}

themeButton.addEventListener('click', () => {
  document.body.classList.toggle('light');
  updateThemeLabel();
  try { localStorage.setItem('portfolio-theme', document.body.classList.contains('light') ? 'light' : 'dark'); } catch {}
});
languageButton.addEventListener('click', () => applyLanguage(language === 'en' ? 'pt' : 'en'));

function updateClock() {
  const date = new Date();
  const el = document.querySelector('#clock');
  el.textContent = new Intl.DateTimeFormat('en-GB', { timeZone:'America/Sao_Paulo', hour:'2-digit', minute:'2-digit' }).format(date);
  el.dateTime = date.toISOString();
  document.querySelector('#year').textContent = date.getFullYear();
}
updateClock();
setInterval(updateClock, 15000);

document.querySelector('#copy').addEventListener('click', async () => {
  const status = document.querySelector('#copy-status');
  try { await navigator.clipboard.writeText('cristian.silvadk22@gmail.com'); status.textContent = translations[language].copied; }
  catch { status.textContent = 'cristian.silvadk22@gmail.com'; }
});

const dialogContent = {
  en: {
    engineering:`<span class="eyebrow">SELECTED EXPERIENCE / MERCADO LIVRE</span><h2>Helping teams build on a shared foundation.</h2><p>I lead frontend development for an internal tax management platform serving teams in Brazil and Argentina. My work connects product interfaces with the architecture and shared tools behind them.</p><h3>Where I contribute</h3><ul><li><strong>Shared components:</strong> created Melitax UI, an internal component library.</li><li><strong>Frontend architecture:</strong> led a migration to microfrontends so teams can work in parallel.</li><li><strong>Authorization:</strong> built shared logic and supported a migration to a new authentication system.</li><li><strong>Team enablement:</strong> documentation, guided examples, technical decisions, and mentoring.</li></ul><p class="eyebrow">REACT · TYPESCRIPT · NODE.JS</p>`,
    spendbox:`<span class="eyebrow">PERSONAL PROJECT / SPENDBOX</span><h2>How big is a billion, really?</h2><p>SpendBox turns an abstract number into a familiar action: shopping. Choose products to buy with a billionaire’s fortune and see how much remains.</p><h3>The idea</h3><p>A playful way to make financial scale tangible, combining product interaction, frontend development, and data.</p><p>Built with React, Chakra UI, Node.js, and TypeScript.</p><a class="primary" href="https://github.com/cristianmacedo" target="_blank" rel="noopener">Visit my GitHub ↗</a>`
  },
  pt: {
    engineering:`<span class="eyebrow">EXPERIÊNCIA EM DESTAQUE / MERCADO LIVRE</span><h2>Ajudando vários times a construir sobre uma fundação compartilhada.</h2><p>Lidero o desenvolvimento frontend de uma plataforma interna de gestão fiscal que atende times no Brasil e na Argentina. Meu trabalho conecta as interfaces do produto à arquitetura e às ferramentas compartilhadas que existem por trás delas.</p><h3>Onde contribuo</h3><ul><li><strong>Componentes compartilhados:</strong> criei a Melitax UI, uma biblioteca interna.</li><li><strong>Arquitetura frontend:</strong> liderei a migração para microfrontends, permitindo que times trabalhem em paralelo.</li><li><strong>Autorização:</strong> construí lógica compartilhada e apoiei a migração para um novo sistema de autenticação.</li><li><strong>Desenvolvimento do time:</strong> documentação, exemplos guiados, decisões técnicas e mentoria.</li></ul><p class="eyebrow">REACT · TYPESCRIPT · NODE.JS</p>`,
    spendbox:`<span class="eyebrow">PROJETO PESSOAL / SPENDBOX</span><h2>Qual é o tamanho de um bilhão?</h2><p>SpendBox transforma um número abstrato em uma ação familiar: comprar. Escolha produtos usando a fortuna de um bilionário e veja quanto ainda resta.</p><h3>A ideia</h3><p>Uma forma divertida de tornar escala financeira tangível, combinando interação de produto, frontend e dados.</p><p>Construído com React, Chakra UI, Node.js e TypeScript.</p><a class="primary" href="https://github.com/cristianmacedo" target="_blank" rel="noopener">Visitar meu GitHub ↗</a>`
  }
};

const dialog = document.querySelector('#detail');
document.querySelectorAll('[data-dialog]').forEach((button) => button.addEventListener('click', () => {
  document.querySelector('#detail-content').innerHTML = dialogContent[language][button.dataset.dialog];
  dialog.showModal();
}));
document.querySelector('.close').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', (event) => {
  if (event.target === dialog) {
    const rect = dialog.getBoundingClientRect();
    if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close();
  }
});

applyLanguage(language);
